"""Fixtures generated by the official LZ4 CLI, independently decoded for hashes."""
from pathlib import Path
import hashlib,json,struct,subprocess,tempfile
ROOT=Path(__file__).resolve().parents[3]
LZ4='/opt/homebrew/bin/lz4'

def fixture(name,raw,plain=None):
    out=ROOT/'tests/fixtures'/name
    out.mkdir(exist_ok=True)
    (out/'sample.lz4').write_bytes(raw)
    expected={'native_format':'lz4_frame','transform':'Lz4Frame','sample':'sample.lz4'}
    if plain is None:
        expected['expect_failure']=True
    else:
        expected['children']={'':{'length':len(plain),'sha256':hashlib.sha256(plain).hexdigest()}}
    (out/'expected.json').write_text(json.dumps(expected,indent=2)+'\n')

with tempfile.TemporaryDirectory() as directory:
    source=Path(directory)/'input'
    plain=(bytes(range(256))+b'LZ4 independently produced fixture\n')*800
    source.write_bytes(plain)
    encoded=[]
    for name,mode in [('lz4_frame','-BI'),('lz4_frame_linked','-BD')]:
        raw=subprocess.check_output([LZ4,'-z','-q','-c','-B4','-BX','--content-size',mode,str(source)])
        assert subprocess.check_output([LZ4,'-d','-q','-c'],input=raw)==plain
        fixture(name,raw,plain)
        encoded.append(raw)
    # Empty stored block is valid and must not be mistaken for end-of-frame.
    empty_plain=b''
    empty=subprocess.check_output([LZ4,'-z','-q','-c'],input=empty_plain)
    empty=empty[:7]+struct.pack('<I',0x80000000)+empty[7:]
    assert subprocess.check_output([LZ4,'-d','-q','-c'],input=empty)==empty_plain
    fixture('lz4_frame_empty_block',empty,empty_plain)
    fixture('lz4_frame_corrupt',encoded[0][:-4])
